code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            comps.append((color, cells))

    def signature(cells):
        pts = [(y-min(r for r,x in cells), x-min(x for r,x in cells)) for y,x in cells]
        variants=[]
        for flip in (1,-1):
            for rot in range(4):
                transformed=[]
                for y,x in pts:
                    x *= flip
                    for _ in range(rot):
                        y,x=x,-y
                    transformed.append((y,x))
                my=min(y for y,x in transformed); mx=min(x for y,x in transformed)
                variants.append(tuple(sorted((y-my,x-mx) for y,x in transformed)))
        return min(variants)

    groups={}
    for color,cells in comps:
        if color == grid[0][0]:
            continue
        groups.setdefault(signature(cells), []).append((color,cells))
    out=[row[:] for row in grid]
    for group in groups.values():
        if len(group) < 2:
            continue
        for i in range(len(group)):
            for j in range(i+1,len(group)):
                col1,cells1=group[i]; col2,cells2=group[j]
                edge1=any(y==0 or x==0 or y==h-1 or x==w-1 for y,x in cells1)
                edge2=any(y==0 or x==0 or y==h-1 or x==w-1 for y,x in cells2)
                if edge1 != edge2:
                    target_color=col1 if edge1 else col2
                    target_cells=cells2 if edge1 else cells1
                    for y,x in target_cells:
                        out[y][x]=target_color
                    return out
    return out
'''
